-- Reported questions and commands: immutable full teaching payload; new normalized bank.
BEGIN;
SET LOCAL lock_timeout='3s';
SET LOCAL statement_timeout='30s';
SELECT pg_advisory_xact_lock(hashtext('grammar-content-import'));
DO $guard$ BEGIN
 IF EXISTS(SELECT 1 FROM grammar.content_releases WHERE version='core-2026-09-v3' AND content_hash<>'e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4') THEN RAISE EXCEPTION 'Published release is immutable'; END IF;
 IF EXISTS(SELECT 1 FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='reported-questions' AND (catalog_hash<>'e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4' OR payload_md5<>'123d18130398bcd0c34d9a7e2fc9e189')) THEN RAISE EXCEPTION 'Catalog payload conflict: use a new version'; END IF;
END $guard$;
INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','reported-questions','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"reported-questions","title":"Reported questions and commands","level":"B1","order":51,"summary":"Embed a question in a report without carrying direct-question word order into the embedded clause.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Yes/no questions use if or whether","Wh-questions keep the question word","Commands use an infinitive pattern","Adjust viewpoint carefully"],"rules":[{"title":"Yes/no questions use if or whether","explanation":"A reported yes/no question commonly starts with asked if or asked whether. The embedded clause has **statement order**, with subject before verb. A report of a question is not itself necessarily a question and usually ends with a full stop.","pattern":"She asked **whether I was ready**.","commonMistakes":["She asked was I ready keeps direct-question order where an embedded clause is needed."],"examples":["Report the question with statement order: “Did she prepare the visitor guide?” → He asked whether **she had prepared the visitor guide**.","Report the question with statement order: “Did she restore the old portrait?” → He asked whether **she had restored the old portrait**."],"skill":"form"},{"title":"Wh-questions keep the question word","explanation":"Who, what, where, when, why and how stay at the start of the embedded clause. Remove do-support when it only formed the direct question and put the lexical verb into the appropriate tense.","pattern":"“Where do you work?” → She asked **where I worked**.","commonMistakes":["Where did I work inside a statement report incorrectly retains inversion and do-support."],"examples":["Report with backshift: “When will they prepare the visitor guide?” → She asked when **they would prepare the visitor guide**.","Report with backshift: “When will they restore the old portrait?” → She asked when **they would restore the old portrait**."],"skill":"meaning"},{"title":"Commands use an infinitive pattern","explanation":"Tell or ask someone **to do** something can report an instruction or request. A negative command uses **not to do**. Keep the person receiving the instruction as the object of told or asked.","pattern":"She told us **to wait**. / She asked us **not to leave**.","commonMistakes":["Told us wait omits to in this reported-command pattern."],"examples":["Report the instruction: “Please prepare the visitor guide.” → She asked us **to prepare the visitor guide**.","Report the instruction: “Please restore the old portrait.” → She asked us **to restore the old portrait**."],"skill":"contrast"},{"title":"Adjust viewpoint carefully","explanation":"Pronouns, time words and backshift depend on the reporting context, just as in reported statements. Subject questions require special care: Who called? already has subject-first order and does not contain removable do-support.","pattern":"He asked **who had called**.","commonMistakes":["Whether is preferred or required in some structures, such as whether to leave and after prepositions; if cannot replace it everywhere."],"examples":["Report “Do not prepare the visitor guide yet.” → She told us **not to prepare the visitor guide yet**.","Report “Do not restore the old portrait yet.” → She told us **not to restore the old portrait yet**."],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-questions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"90f4c17a-f2f8-572d-a7b7-9d130ddd7918","topicSlug":"reported-questions","level":"B1","prompt":"Report the question with statement order: “Did she prepare the visitor guide?” → He asked whether ____.","choices":[{"id":"A","text":"she had prepared the visitor guide"},{"id":"B","text":"had she prepared the visitor guide"},{"id":"C","text":"did she prepare the visitor guide"},{"id":"D","text":"she did prepared the visitor guide"}],"answerId":"A","hint":"An embedded question uses **subject before verb**.","explanation":"After **whether**, use subject **she** before **had prepared** in this backshifted report.","keywords":["reported-yes-no"],"skill":"reported-yes-no","contextKey":"reported-questions-1","fingerprint":"92e32ba73bdba2b829c1e0ae2b4ca9a7ffaed7751199b7080391357cdf035af0","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-questions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["An embedded question uses **subject before verb**.","After **whether**, use subject **she** before **had prepared** in this backshifted report.","Choose **she had prepared the visitor guide**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"After **whether**, use subject **she** before **had prepared** in this backshifted report.","B":"This keeps question inversion inside the embedded clause.","C":"This keeps direct-question do-support and inversion.","D":"After did, a main verb must be base; this is not the requested backshifted structure."}}},{"id":"45d88597-0a5e-5794-a173-073b183b0beb","topicSlug":"reported-questions","level":"B1","prompt":"Report with backshift: “When will they prepare the visitor guide?” → She asked when ____.","choices":[{"id":"A","text":"they would to prepare the visitor guide"},{"id":"B","text":"they would prepared the visitor guide"},{"id":"C","text":"they would prepare the visitor guide"},{"id":"D","text":"would they prepare the visitor guide"}],"answerId":"C","hint":"Keep the question word, but **remove inversion** in the report.","explanation":"Keep when, then use **they would prepare** in statement order.","keywords":["reported-wh-order"],"skill":"reported-wh-order","contextKey":"reported-questions-1","fingerprint":"f088c778a4d16999eac15bc9a67fe436cc7b1ca048ba9a5fb7fd2b371dbee4c7","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-questions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Keep the question word, but **remove inversion** in the report.","Keep when, then use **they would prepare** in statement order.","Choose **they would prepare the visitor guide**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Would takes a bare infinitive.","B":"The verb after would stays base.","C":"Keep when, then use **they would prepare** in statement order.","D":"The subject must precede would inside the embedded question."}}},{"id":"b5760140-1d9a-5e97-aca8-7d6f99779714","topicSlug":"reported-questions","level":"B1","prompt":"Report the instruction: “Please prepare the visitor guide.” → She asked us ____.","choices":[{"id":"A","text":"that prepare the visitor guide"},{"id":"B","text":"to prepare the visitor guide"},{"id":"C","text":"prepare the visitor guide"},{"id":"D","text":"prepared the visitor guide"}],"answerId":"B","hint":"Report the instruction with **ask + person + to-infinitive**.","explanation":"A reported request uses **asked us to prepare**.","keywords":["reported-command"],"skill":"reported-command","contextKey":"reported-questions-1","fingerprint":"e2f77bc9c9c6027f691a3652d24514b9ce3496df9f733e511dbe080b7dc195bb","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-questions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Report the instruction with **ask + person + to-infinitive**.","A reported request uses **asked us to prepare**.","Choose **to prepare the visitor guide**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"That would need a complete finite clause, not a bare verb.","B":"A reported request uses **asked us to prepare**.","C":"The reported-request pattern needs to before the infinitive.","D":"A past form does not complete asked us in this request pattern."}}},{"id":"4d544d62-68d0-56d3-a00a-a895dba284af","topicSlug":"reported-questions","level":"B1","prompt":"Report “Do not prepare the visitor guide yet.” → She told us ____.","choices":[{"id":"A","text":"not to prepared the visitor guide yet"},{"id":"B","text":"not to prepare the visitor guide yet"},{"id":"C","text":"do not prepare the visitor guide yet"},{"id":"D","text":"not prepare the visitor guide yet"}],"answerId":"B","hint":"Put **not before to** in a reported negative instruction.","explanation":"The negative reported instruction is **told us not to prepare**.","keywords":["negative-reported-command"],"skill":"negative-reported-command","contextKey":"reported-questions-1","fingerprint":"be942f95a5bfacd714357f9d1f558db1dc0f4c82d3e78969f000c824e50d060e","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-questions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Put **not before to** in a reported negative instruction.","The negative reported instruction is **told us not to prepare**.","Choose **not to prepare the visitor guide yet**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"After to, use the base form, not the past form.","B":"The negative reported instruction is **told us not to prepare**.","C":"This keeps the direct imperative instead of using a reported infinitive.","D":"To is missing before the infinitive."}}},{"id":"e499b00d-6178-5db4-a71a-4683dce096b7","topicSlug":"reported-questions","level":"B1","prompt":"Report the question with statement order: “Did she restore the old portrait?” → He asked whether ____.","choices":[{"id":"A","text":"did she restore the old portrait"},{"id":"B","text":"she did restored the old portrait"},{"id":"C","text":"she had restored the old portrait"},{"id":"D","text":"had she restored the old portrait"}],"answerId":"C","hint":"An embedded question uses **subject before verb**.","explanation":"After **whether**, use subject **she** before **had restored** in this backshifted report.","keywords":["reported-yes-no"],"skill":"reported-yes-no","contextKey":"reported-questions-2","fingerprint":"7a0b7f6a075281164f3c5b760d21721f44e7e1ccde77ba6f4bc563da4a8e5363","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-questions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["An embedded question uses **subject before verb**.","After **whether**, use subject **she** before **had restored** in this backshifted report.","Choose **she had restored the old portrait**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This keeps direct-question do-support and inversion.","B":"After did, a main verb must be base; this is not the requested backshifted structure.","C":"After **whether**, use subject **she** before **had restored** in this backshifted report.","D":"This keeps question inversion inside the embedded clause."}}},{"id":"de0d9331-8846-5d34-aed5-361bfc24c3eb","topicSlug":"reported-questions","level":"B1","prompt":"Report with backshift: “When will they restore the old portrait?” → She asked when ____.","choices":[{"id":"A","text":"they would restored the old portrait"},{"id":"B","text":"they would restore the old portrait"},{"id":"C","text":"would they restore the old portrait"},{"id":"D","text":"they would to restore the old portrait"}],"answerId":"B","hint":"Keep the question word, but **remove inversion** in the report.","explanation":"Keep when, then use **they would restore** in statement order.","keywords":["reported-wh-order"],"skill":"reported-wh-order","contextKey":"reported-questions-2","fingerprint":"b46b5588f7b8b52c4cbd4028b9d998603f59a86bac3dbbe7c99990f53fee51d9","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-questions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Keep the question word, but **remove inversion** in the report.","Keep when, then use **they would restore** in statement order.","Choose **they would restore the old portrait**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The verb after would stays base.","B":"Keep when, then use **they would restore** in statement order.","C":"The subject must precede would inside the embedded question.","D":"Would takes a bare infinitive."}}},{"id":"7ec7bba7-e779-58b6-a627-62dc788617e7","topicSlug":"reported-questions","level":"B1","prompt":"Report the instruction: “Please restore the old portrait.” → She asked us ____.","choices":[{"id":"A","text":"restore the old portrait"},{"id":"B","text":"restored the old portrait"},{"id":"C","text":"that restore the old portrait"},{"id":"D","text":"to restore the old portrait"}],"answerId":"D","hint":"Report the instruction with **ask + person + to-infinitive**.","explanation":"A reported request uses **asked us to restore**.","keywords":["reported-command"],"skill":"reported-command","contextKey":"reported-questions-2","fingerprint":"3ef7ff141c98cf64317d9f69de77fcd79adc42a79c60584b917d630b6c30ac9a","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-questions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Report the instruction with **ask + person + to-infinitive**.","A reported request uses **asked us to restore**.","Choose **to restore the old portrait**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The reported-request pattern needs to before the infinitive.","B":"A past form does not complete asked us in this request pattern.","C":"That would need a complete finite clause, not a bare verb.","D":"A reported request uses **asked us to restore**."}}},{"id":"b63573b5-e47d-5ca9-af82-08b05435497c","topicSlug":"reported-questions","level":"B1","prompt":"Report “Do not restore the old portrait yet.” → She told us ____.","choices":[{"id":"A","text":"not to restored the old portrait yet"},{"id":"B","text":"not to restore the old portrait yet"},{"id":"C","text":"do not restore the old portrait yet"},{"id":"D","text":"not restore the old portrait yet"}],"answerId":"B","hint":"Put **not before to** in a reported negative instruction.","explanation":"The negative reported instruction is **told us not to restore**.","keywords":["negative-reported-command"],"skill":"negative-reported-command","contextKey":"reported-questions-2","fingerprint":"0fee31fcd4a0b8b3e0b5a861ee15421c209f045fe874fc003d62e5a1912e86a8","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-questions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Put **not before to** in a reported negative instruction.","The negative reported instruction is **told us not to restore**.","Choose **not to restore the old portrait yet**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"After to, use the base form, not the past form.","B":"The negative reported instruction is **told us not to restore**.","C":"This keeps the direct imperative instead of using a reported infinitive.","D":"To is missing before the infinitive."}}},{"id":"ad387e18-cffd-54cc-a215-677dfd5b591a","topicSlug":"reported-questions","level":"B1","prompt":"Report the question with statement order: “Did she measure the garden fence?” → He asked whether ____.","choices":[{"id":"A","text":"she did measured the garden fence"},{"id":"B","text":"she had measured the garden fence"},{"id":"C","text":"had she measured the garden fence"},{"id":"D","text":"did she measure the garden fence"}],"answerId":"B","hint":"An embedded question uses **subject before verb**.","explanation":"After **whether**, use subject **she** before **had measured** in this backshifted report.","keywords":["reported-yes-no"],"skill":"reported-yes-no","contextKey":"reported-questions-3","fingerprint":"5266deb544d45a8a7ade9df188967dcfd001ba96ec1e2310def9a3d3178118c8","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-questions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["An embedded question uses **subject before verb**.","After **whether**, use subject **she** before **had measured** in this backshifted report.","Choose **she had measured the garden fence**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"After did, a main verb must be base; this is not the requested backshifted structure.","B":"After **whether**, use subject **she** before **had measured** in this backshifted report.","C":"This keeps question inversion inside the embedded clause.","D":"This keeps direct-question do-support and inversion."}}},{"id":"9a2e24f6-35b1-5e56-a1bf-214f9d9b79c3","topicSlug":"reported-questions","level":"B1","prompt":"Report with backshift: “When will they measure the garden fence?” → She asked when ____.","choices":[{"id":"A","text":"they would to measure the garden fence"},{"id":"B","text":"they would measured the garden fence"},{"id":"C","text":"they would measure the garden fence"},{"id":"D","text":"would they measure the garden fence"}],"answerId":"C","hint":"Keep the question word, but **remove inversion** in the report.","explanation":"Keep when, then use **they would measure** in statement order.","keywords":["reported-wh-order"],"skill":"reported-wh-order","contextKey":"reported-questions-3","fingerprint":"ff1c6cb606cebe1938d1505fff34c1607cdf8f7f3247bbd5b59b41e33b506b85","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-questions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Keep the question word, but **remove inversion** in the report.","Keep when, then use **they would measure** in statement order.","Choose **they would measure the garden fence**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Would takes a bare infinitive.","B":"The verb after would stays base.","C":"Keep when, then use **they would measure** in statement order.","D":"The subject must precede would inside the embedded question."}}},{"id":"e95839f1-08b5-57e3-ae40-6b57ec9433f5","topicSlug":"reported-questions","level":"B1","prompt":"Report the instruction: “Please measure the garden fence.” → She asked us ____.","choices":[{"id":"A","text":"that measure the garden fence"},{"id":"B","text":"to measure the garden fence"},{"id":"C","text":"measure the garden fence"},{"id":"D","text":"measured the garden fence"}],"answerId":"B","hint":"Report the instruction with **ask + person + to-infinitive**.","explanation":"A reported request uses **asked us to measure**.","keywords":["reported-command"],"skill":"reported-command","contextKey":"reported-questions-3","fingerprint":"f1974c09aa891c20f14645194a0a9d0515d137b1afab0f849cc6b03335b08080","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-questions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Report the instruction with **ask + person + to-infinitive**.","A reported request uses **asked us to measure**.","Choose **to measure the garden fence**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"That would need a complete finite clause, not a bare verb.","B":"A reported request uses **asked us to measure**.","C":"The reported-request pattern needs to before the infinitive.","D":"A past form does not complete asked us in this request pattern."}}},{"id":"6e814152-91c1-5030-ac07-dabaa19b5499","topicSlug":"reported-questions","level":"B1","prompt":"Report “Do not measure the garden fence yet.” → She told us ____.","choices":[{"id":"A","text":"not to measured the garden fence yet"},{"id":"B","text":"not to measure the garden fence yet"},{"id":"C","text":"do not measure the garden fence yet"},{"id":"D","text":"not measure the garden fence yet"}],"answerId":"B","hint":"Put **not before to** in a reported negative instruction.","explanation":"The negative reported instruction is **told us not to measure**.","keywords":["negative-reported-command"],"skill":"negative-reported-command","contextKey":"reported-questions-3","fingerprint":"47c4bbd721682a8cafb9c381e45dba593c6c099925e2d477cfdd977a07c85d70","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-questions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Put **not before to** in a reported negative instruction.","The negative reported instruction is **told us not to measure**.","Choose **not to measure the garden fence yet**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"After to, use the base form, not the past form.","B":"The negative reported instruction is **told us not to measure**.","C":"This keeps the direct imperative instead of using a reported infinitive.","D":"To is missing before the infinitive."}}},{"id":"3c058d82-ec59-5448-afd0-4609a3a4d46e","topicSlug":"reported-questions","level":"B1","prompt":"Report the question with statement order: “Did she translate the travel leaflet?” → He asked whether ____.","choices":[{"id":"A","text":"she did translated the travel leaflet"},{"id":"B","text":"she had translated the travel leaflet"},{"id":"C","text":"had she translated the travel leaflet"},{"id":"D","text":"did she translate the travel leaflet"}],"answerId":"B","hint":"An embedded question uses **subject before verb**.","explanation":"After **whether**, use subject **she** before **had translated** in this backshifted report.","keywords":["reported-yes-no"],"skill":"reported-yes-no","contextKey":"reported-questions-4","fingerprint":"73706951cf4df959d72bfea4d6bbfd96c917a0313140a1ce8bae065970cfcd6c","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-questions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["An embedded question uses **subject before verb**.","After **whether**, use subject **she** before **had translated** in this backshifted report.","Choose **she had translated the travel leaflet**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"After did, a main verb must be base; this is not the requested backshifted structure.","B":"After **whether**, use subject **she** before **had translated** in this backshifted report.","C":"This keeps question inversion inside the embedded clause.","D":"This keeps direct-question do-support and inversion."}}},{"id":"f0acf17a-e8d3-5b8b-a206-b7b09c0ebd94","topicSlug":"reported-questions","level":"B1","prompt":"Report with backshift: “When will they translate the travel leaflet?” → She asked when ____.","choices":[{"id":"A","text":"they would translated the travel leaflet"},{"id":"B","text":"they would translate the travel leaflet"},{"id":"C","text":"would they translate the travel leaflet"